1	export type Item = { type: string };
2	export type Step = { items: Item[] };
3	export type Scenario = { steps: Step[] };
4	export type Result = { premium: number };
5	export type ScenarioOutcome = { results: Result[] };
6	
7	const BASE_PREMIUMS: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	
14	const FIRST_INSURANCE_SURCHARGE = 1.1;
15	const PROCESSING_FEE = 5;
16	
17	const roundUpToWholeGold = (amount: number): number =>
18	  Math.ceil(Number(amount.toFixed(6)));
19	
20	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
21	  const basePremium = BASE_PREMIUMS[scenario.steps[0].items[0].type];
22	  const premium =
23	    roundUpToWholeGold(basePremium * FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
24	  return { results: [{ premium }] };
25	};
